        long long MOD = 1e9 + 7;
        long long ends0 = 0, ends1 = 0;
        int hasZero = 0;
        for (char ch : binary) {
            if (ch == '1') {
                ends1 = (ends0 + ends1 + 1) % MOD;
            } else {
                ends0 = (ends0 + ends1) % MOD;
                hasZero = 1;
            }
        }
        return (ends0 + ends1 + hasZero) % MOD;
